package com.bruhsailor.plugin;

import java.util.Objects;

public final class StepId implements Comparable<StepId>
{
    private final int chapter;
    private final int section;
    private final int step;

    private StepId(int chapter, int section, int step)
    {
        this.chapter = chapter;
        this.section = section;
        this.step = step;
    }

    public static StepId of(int chapter, int section, int step)
    {
        if (chapter < 1 || section < 1 || step < 1)
        {
            throw new IllegalArgumentException("StepId components must be >= 1");
        }
        return new StepId(chapter, section, step);
    }

    public static StepId parse(String s)
    {
        String[] parts = s.split("\\.");
        if (parts.length != 3)
        {
            throw new IllegalArgumentException("Expected chapter.section.step, got: " + s);
        }
        try
        {
            return of(
                Integer.parseInt(parts[0]),
                Integer.parseInt(parts[1]),
                Integer.parseInt(parts[2])
            );
        }
        catch (NumberFormatException e)
        {
            throw new IllegalArgumentException("Non-numeric component in: " + s, e);
        }
    }

    public int chapter() { return chapter; }
    public int section() { return section; }
    public int step() { return step; }

    @Override
    public int compareTo(StepId o)
    {
        int c = Integer.compare(chapter, o.chapter);
        if (c != 0) return c;
        c = Integer.compare(section, o.section);
        if (c != 0) return c;
        return Integer.compare(step, o.step);
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof StepId)) return false;
        StepId other = (StepId) o;
        return chapter == other.chapter && section == other.section && step == other.step;
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(chapter, section, step);
    }

    @Override
    public String toString()
    {
        return chapter + "." + section + "." + step;
    }
}

package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.StepMapping;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

public final class StepMappings
{
    private static final Logger log = LoggerFactory.getLogger(StepMappings.class);
    private static final String RESOURCE = "/step_mappings.json";

    private final Map<StepId, StepMapping> byId;

    private StepMappings(Map<StepId, StepMapping> byId)
    {
        this.byId = Collections.unmodifiableMap(byId);
    }

    public static StepMappings empty()
    {
        return new StepMappings(Collections.emptyMap());
    }

    public static StepMappings loadBundled(Gson gson)
    {
        InputStream in = StepMappings.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            throw new IllegalStateException("Missing classpath resource " + RESOURCE);
        }
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            JsonObject root = gson.fromJson(r, JsonObject.class);
            JsonObject steps = root.getAsJsonObject("steps");
            Map<StepId, StepMapping> map = new HashMap<>();
            for (Map.Entry<String, JsonElement> e : steps.entrySet())
            {
                StepId id;
                try
                {
                    id = StepId.parse(e.getKey());
                }
                catch (IllegalArgumentException ex)
                {
                    log.warn("Skipping malformed step_mappings key: {}", e.getKey());
                    continue;
                }
                StepMapping m = gson.fromJson(e.getValue(), StepMapping.class);
                map.put(id, m);
            }
            return new StepMappings(map);
        }
        catch (Exception e)
        {
            throw new IllegalStateException("Failed to parse " + RESOURCE, e);
        }
    }

    public int size()
    {
        return byId.size();
    }

    public Optional<StepMapping> findById(StepId id)
    {
        return Optional.ofNullable(byId.get(id));
    }

    public Set<StepId> allIds()
    {
        return byId.keySet();
    }
}

package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.GuideData;
import com.bruhsailor.plugin.model.Step;
import com.google.gson.Gson;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class GuideRepository
{
    private static final String RESOURCE = "/guide_data.json";

    private final String updatedOn;
    private final List<Step> steps;
    private final Map<StepId, Step> byId;
    private final Map<StepId, Integer> indexById;
    private final Map<StepId, String> chapterTitleByStep;
    private final Map<StepId, String> sectionTitleByStep;

    private GuideRepository(
        String updatedOn,
        List<Step> steps,
        Map<StepId, Step> byId,
        Map<StepId, Integer> indexById,
        Map<StepId, String> chapterTitleByStep,
        Map<StepId, String> sectionTitleByStep)
    {
        this.updatedOn = updatedOn;
        this.steps = Collections.unmodifiableList(steps);
        this.byId = byId;
        this.indexById = indexById;
        this.chapterTitleByStep = chapterTitleByStep;
        this.sectionTitleByStep = sectionTitleByStep;
    }

    public static GuideRepository loadBundled(Gson gson)
    {
        InputStream in = GuideRepository.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            throw new IllegalStateException("Missing classpath resource " + RESOURCE);
        }
        GuideData data;
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            data = gson.fromJson(r, GuideData.class);
        }
        catch (Exception e)
        {
            throw new IllegalStateException("Failed to parse " + RESOURCE, e);
        }
        return build(data);
    }

    private static GuideRepository build(GuideData data)
    {
        List<Step> flat = new ArrayList<>();
        Map<StepId, Step> byId = new HashMap<>();
        Map<StepId, Integer> indexById = new HashMap<>();
        Map<StepId, String> chapterTitle = new HashMap<>();
        Map<StepId, String> sectionTitle = new HashMap<>();

        for (int ci = 0; ci < data.chapters.size(); ci++)
        {
            GuideData.Chapter chapter = data.chapters.get(ci);
            for (int si = 0; si < chapter.sections.size(); si++)
            {
                GuideData.Section section = chapter.sections.get(si);
                for (int ti = 0; ti < section.steps.size(); ti++)
                {
                    Step step = section.steps.get(ti);
                    StepId id = StepId.of(ci + 1, si + 1, ti + 1);
                    step.id = id;
                    indexById.put(id, flat.size());
                    flat.add(step);
                    byId.put(id, step);
                    chapterTitle.put(id, chapter.title);
                    sectionTitle.put(id, section.title);
                }
            }
        }

        return new GuideRepository(data.updatedOn, flat, byId, indexById, chapterTitle, sectionTitle);
    }

    /** Guide version date (e.g. "2026-08-30"); keys persisted progress for {@link StepIdMigrations}. */
    public String updatedOn()
    {
        return updatedOn;
    }

    public List<Step> steps()
    {
        return steps;
    }

    public Optional<Step> findById(StepId id)
    {
        return Optional.ofNullable(byId.get(id));
    }

    public int indexOf(StepId id)
    {
        Integer i = indexById.get(id);
        return i == null ? -1 : i;
    }

    public Optional<StepId> idAt(int index)
    {
        if (index < 0 || index >= steps.size()) return Optional.empty();
        return Optional.of(steps.get(index).id);
    }

    public String chapterTitleFor(StepId id)
    {
        return chapterTitleByStep.get(id);
    }

    public String sectionTitleFor(StepId id)
    {
        return sectionTitleByStep.get(id);
    }
}

package com.bruhsailor.plugin;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public final class QuestRegistry
{
    private static final Logger log = LoggerFactory.getLogger(QuestRegistry.class);
    private static final String RESOURCE = "/quests.json";

    private final Map<String, QuestEntry> byEnumName;

    private QuestRegistry(Map<String, QuestEntry> byEnumName)
    {
        this.byEnumName = Collections.unmodifiableMap(byEnumName);
    }

    public static QuestRegistry create(Gson gson)
    {
        Map<String, QuestEntry> map = new HashMap<>();
        loadBundled(map, gson);
        return new QuestRegistry(map);
    }

    private static void loadBundled(Map<String, QuestEntry> map, Gson gson)
    {
        InputStream in = QuestRegistry.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            log.error("Missing classpath resource {}", RESOURCE);
            return;
        }
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            JsonObject root = gson.fromJson(r, JsonObject.class);
            JsonArray quests = root.getAsJsonArray("quests");
            for (JsonElement e : quests)
            {
                JsonObject q = e.getAsJsonObject();
                String enumName = q.get("enumName").getAsString();
                String displayName = q.get("displayName").getAsString();
                java.util.List<String> aliases = new java.util.ArrayList<>();
                if (q.has("aliases") && q.get("aliases").isJsonArray())
                {
                    for (JsonElement a : q.getAsJsonArray("aliases")) aliases.add(a.getAsString());
                }
                if (q.has("shortAliases") && q.get("shortAliases").isJsonArray())
                {
                    for (JsonElement a : q.getAsJsonArray("shortAliases")) aliases.add(a.getAsString());
                }
                map.put(enumName, new QuestEntry(enumName, displayName, aliases));
            }
        }
        catch (Exception e)
        {
            log.error("Failed to parse {}", RESOURCE, e);
        }
    }

    public int size()
    {
        return byEnumName.size();
    }

    public Optional<QuestEntry> resolve(String enumName)
    {
        if (enumName == null) return Optional.empty();
        return Optional.ofNullable(byEnumName.get(enumName));
    }
}

